const dictionaries: Record<Lang, Dict> = {
  en,
  fil: { ...fil, ...legalDicts.fil },
  es: { ...es, ...legalDicts.es },
  hi: { ...hi, ...legalDicts.hi },
  bn: { ...bn, ...legalDicts.bn },
  id: { ...id, ...legalDicts.id },
  ms: { ...ms, ...legalDicts.ms },
  th: { ...th, ...legalDicts.th },
  vi: { ...vi, ...legalDicts.vi },
  pt: { ...pt, ...legalDicts.pt },
  fr: { ...fr, ...legalDicts.fr },
  de: { ...de, ...legalDicts.de },
  zh: { ...zh, ...legalDicts.zh },
  ja: { ...ja, ...legalDicts.ja },
  ko: { ...ko, ...legalDicts.ko },
  ar: { ...ar, ...legalDicts.ar },
};

interface LangState {
  lang: Lang;
  /** When true, the CURRENCY follows the device/GPS location automatically. Language
   *  is independent of this — it always defaults to English and is chosen manually. */
  autoRegion: boolean;
  setLang: (lang: Lang) => void;
  applyLang: (lang: Lang) => void;
  setAutoRegion: (auto: boolean) => void;
}

export const useLangStore = create<LangState>()(
  persist(
    (set) => ({
      // Default to English everywhere; users switch language manually in Settings.
      lang: "en",
      autoRegion: true,
      // Language is a manual, independent choice (does not touch currency auto mode).
      setLang: (lang) => set({ lang }),
      applyLang: (lang) => set({ lang }),
      setAutoRegion: (autoRegion) => set({ autoRegion }),
    }),
    { name: "masaya_lang" },
  ),
);

// Set text direction (RTL for Arabic) on the document.
export function applyDirection(lang: Lang) {
  if (typeof document === "undefined") return;
  document.documentElement.dir = RTL_LANGS.includes(lang) ? "rtl" : "ltr";
  document.documentElement.lang = lang;
}

function interpolate(text: string, vars?: Record<string, string>) {
  if (!vars) return text;
  let out = text;
  for (const [k, v] of Object.entries(vars)) out = out.replace(`{${k}}`, v);
  return out;
}

function lookup(lang: Lang, key: TKey, vars?: Record<string, string>) {
  return interpolate(dictionaries[lang]?.[key] ?? en[key] ?? key, vars);
}

/** Keys that carry one string per CLDR plural category, e.g. fb_members_one. */
export type PluralKey = "fb_members";

/**
 * Building an Intl.PluralRules is not free and these run inside list renders,
 * so keep one per language.
 */
const pluralRules = new Map<Lang, Intl.PluralRules>();
function rulesFor(lang: Lang): Intl.PluralRules {
  let rules = pluralRules.get(lang);
  if (!rules) {
    try {
      rules = new Intl.PluralRules(lang);
    } catch {
      // An engine that does not know the tag still has to render something.
      rules = new Intl.PluralRules("en");
    }
    pluralRules.set(lang, rules);
  }
  return rules;
}

/**
 * Plural-aware lookup.
 *
 * "1 members" is wrong in English and worse elsewhere: Arabic distinguishes
 * six categories, Chinese and Japanese none at all, so neither `count === 1`
 * nor bolting an "s" on the end works. Ask Intl.PluralRules which category the
 * number falls into for this language and read that variant.
 *
 * Falls back to the `_other` form and then to English, so a language missing a
 * category renders a real word rather than a raw key.
 */
function lookupPlural(
  lang: Lang,
  key: PluralKey,
  count: number,
  vars?: Record<string, string>,
) {
  const category = rulesFor(lang).select(count);
  const exact = `${key}_${category}` as TKey;
  const other = `${key}_other` as TKey;
  const dict = dictionaries[lang];
  const text = dict?.[exact] ?? dict?.[other] ?? en[exact] ?? en[other] ?? key;
  return interpolate(text, { count: count.toLocaleString(lang), ...vars });
}

/**
 * Non-reactive translator for code that runs outside React: thrown errors and
 * the notifications stores push. Reads the language at call time, which is the
 * moment the string is shown, so it is always the driver's current language.
 */
export function translate(key: TKey, vars?: Record<string, string>) {
  return lookup(useLangStore.getState().lang, key, vars);
}

// Reactive translator hook. Usage: const t = useT(); t("nav_home").
export function useT() {
  const lang = useLangStore((state) => state.lang);
  return (key: TKey, vars?: Record<string, string>) => lookup(lang, key, vars);
}

/**
 * Reactive plural translator. Usage: const p = usePlural(); p("fb_members", 1).
 * `{count}` is supplied automatically, localised for the driver's language.
 */
export function usePlural() {
  const lang = useLangStore((state) => state.lang);
  return (key: PluralKey, count: number, vars?: Record<string, string>) =>
    lookupPlural(lang, key, count, vars);
}
